inputs = ['ubkhb', 'hd', 'kd', 'bg', 'wuu']
outputs = ['bywbkhb', 'jf', 'kef', 'bg', 'wbywbyw']

# Focus on the changed pairs
changed_pairs = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changed_pairs.append((i, inp, outp))

print("Changed pairs:")
for idx, inp, outp in changed_pairs:
    print(f"  {idx}: '{inp}' -> '{outp}'")

# Let me examine the first few pairs more carefully to understand their differences
print("\nDetailed analysis:")
for idx, inp, outp in changed_pairs:
    print(f"Example {idx}: '{inp}' -> '{outp}'")
    if len(inp) <= len(outp):
        # Look for insertions or replacements
        for i in range(len(inp)):
            if i < len(outp) and inp[i] != outp[i]:
                print(f"  First difference at position {i}: '{inp[i]}' -> '{outp[i]}'")
                break
        else:
            if len(outp) > len(inp):
                print(f"  Insertion at end: length increased from {len(inp)} to {len(outp)}")
    else:
        print(f"  Length decreased from {len(inp)} to {len(outp)}")
    print()

